#!/usr/bin/env node
/**
 * OmniFlow — Soale Vercel + Supabase Supavisor (:6543) Complete Resilience Patcher
 * Range: soale-phase-7..soale-vercel-db-fix (3 files, idempotent)
 *
 * Fixes:
 *   1. Eliminates Supavisor (:6543) query-pipelining deadlock (Diagnostic Digest: 583971903
 *      at 15.25s on /, /services/[slug], /blog/[slug], /case-studies/[slug]) via a
 *      re-entrant 3-slot semaphore (withPgConcurrencySlot) paired with max: 6 sockets
 *      and fetch_types: false so postgres.js never pipelines onto a busy socket.
 *   2. Collapses all 8 public read collections + pages + active redirects into ONE
 *      zero-parameter Simple Query (loadPostgresPublicCatalogBundle, 3s cache, instant
 *      mutation invalidation) + 1 batched kv_configs query (loadPostgresKvBundle).
 *   3. Single-CTE atomic baseline seed across all 7 tables + URL query sanitizer + /favicon.ico.
 *
 * Usage:
 *   node patches/soale-vercel-db-fix.mjs --dry-run
 *   node patches/soale-vercel-db-fix.mjs
 */
import fs from "node:fs";
import path from "node:path";

const DRY_RUN = process.argv.includes("--dry-run");
const ROOT = process.cwd();

const OPERATIONS = [
  {
    "op": "write",
    "path": "src/app/favicon.ico/route.ts",
    "base64": ""
  },
  {
    "op": "write",
    "path": "src/lib/database/index.ts",
    "base64": ""
  },
  {
    "op": "write",
    "path": "tests/soale-vercel-db-resilience.test.ts",
    "base64": ""
  }
];

if (!fs.existsSync(path.join(ROOT, "package.json"))) {
  console.error("Error: Run this patcher from the OmniFlow repository root (where package.json lives).");
  process.exit(1);
}

let written = 0;
let deleted = 0;

for (const item of OPERATIONS) {
  const target = path.join(ROOT, item.path);
  if (item.op === "delete") {
    if (DRY_RUN) {
      console.log("[DRY-RUN] DELETE", item.path);
    } else if (fs.existsSync(target)) {
      fs.unlinkSync(target);
      console.log("DELETED", item.path);
    }
    deleted++;
  } else {
    const buf = Buffer.from(item.base64, "base64");
    if (DRY_RUN) {
      console.log(`[DRY-RUN] WRITE  ${item.path} (${buf.length} bytes)`);
    } else {
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.writeFileSync(target, buf);
      console.log(`WROTE   ${item.path} (${buf.length} bytes)`);
    }
    written++;
  }
}

console.log(
  DRY_RUN
    ? `\nDry-run complete: ${written} file(s) would be written, ${deleted} deleted.`
    : `\nApplied Soale Vercel + Supavisor Hotfix v3: ${written} file(s) written, ${deleted} deleted.`
);
